import * as React from "react";

export type BanjoRoundIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function BanjoRoundIcon({ size = 20, ...props }: BanjoRoundIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="10" cy="15" r="5.5" /><path d="M13.5 10.5 19 4M17 4h3v3" />
    </svg>
  );
}
